package org.apache.commons.math.linear;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_45_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        try {
            // Attempt to create a matrix with zero dimensions
            OpenMapRealMatrix matrix = new OpenMapRealMatrix(0, 0);
            // If no exception is thrown, check if dimensions are set correctly
            assertEquals(0, matrix.getRowDimension());
            assertEquals(0, matrix.getColumnDimension());
        } catch (Exception e) {
            // If an exception is thrown, it should be a specific type
            fail("Unexpected exception: " + e.getMessage());
        }
    }
}

